<?php get_header();the_post();$terms=get_the_terms(get_the_ID(),'vatan_category');$category=$terms&&!is_wp_error($terms)?$terms[0]:null;vatan_intro(get_the_title(),get_the_excerpt(),$category?'محصولات / '.$category->name:'محصولات وطن'); ?><section class="section"><div class="wrap split"><div><?php if(has_post_thumbnail()){the_post_thumbnail('large',['class'=>'product-image']);} ?><div class="editorial"><?php the_content(); ?></div></div><aside class="panel"><span class="eyebrow">مشخصات محصول</span><?php $specs=get_post_meta(get_the_ID(),'_vatan_specs',true);if($specs){ ?><table class="specs"><tbody><?php foreach(explode("\n",$specs) as $line){$pair=explode('|',$line,2);if(count($pair)===2)echo '<tr><th>'.esc_html(trim($pair[0])).'</th><td>'.esc_html(trim($pair[1])).'</td></tr>';} ?></tbody></table><?php } ?><p class="form-note"><?php echo esc_html(get_post_meta(get_the_ID(),'_vatan_availability',true)?:'برای بررسی موجودی و شرایط تامین، استعلام ثبت کنید.'); ?></p><a class="button" href="<?php echo esc_url(add_query_arg(['category'=>$category?$category->slug:'','product'=>get_the_title()],vatan_url('inquiry/'))); ?>">استعلام این محصول</a><?php $wa=preg_replace('/\D/','',vatan_option('whatsapp'));if($wa){ ?><div class="actions"><a class="button ghost" href="<?php echo esc_url('https://wa.me/'.$wa.'?text='.rawurlencode('سلام، درباره '.get_the_title().' در سایت وطن استعلام دارم. '.get_permalink())); ?>" target="_blank" rel="noopener noreferrer">گفتگو در واتس‌اپ</a></div><?php } ?></aside></div></section><?php
if($category){$q=new WP_Query(['post_type'=>'vatan_product','posts_per_page'=>3,'post__not_in'=>[get_the_ID()],'tax_query'=>[['taxonomy'=>'vatan_category','field'=>'term_id','terms'=>$category->term_id]]]);if($q->have_posts()){ ?><section class="section"><div class="wrap"><h2>در همین گروه</h2><div class="content-grid"><?php while($q->have_posts()){$q->the_post();vatan_product_card(get_post());} ?></div></div></section><?php wp_reset_postdata();}}get_footer(); ?>
